def merge_sorted_list(*inputs):
    heap = []
    result = []

    # Initialize the heap with the first element of each input list
    for i, input_list in enumerate(inputs):
        if input_list:
            heapq.heappush(heap, (input_list[0], i, 0))

    while heap:
        value, list_index, element_index = heapq.heappop(heap)
        result.append(value)

        # If there are more elements in the current list, push the next element onto the heap
        if element_index + 1 < len(inputs[list_index]):
            next_element = inputs[list_index][element_index + 1]
            heapq.heappush(heap, (next_element, list_index, element_index + 1))

    return result

