import math

def calculate_polygons(x1, y1, x2, y2, n):
    def hexagon_coordinates(x, y, side_length):
        angle_deg = 60
        angle_rad = math.radians(angle_deg)
        coordinates = []
        for i in range(6):
            x_new = x + side_length * math.cos(i * angle_rad)
            y_new = y + side_length * math.sin(i * angle_rad)
            coordinates.append((x_new, y_new))
        return coordinates

    def grid_coordinates(x1, y1, x2, y2, n):
        side_length = (x2 - x1) / (n + 1)
        coordinates = []
        for i in range(n + 1):
            for j in range(n + 1):
                x = x1 + i * side_length
                y = y1 + j * side_length * math.sqrt(3)
                coordinates.append((x, y))
        return coordinates

    def hexagon_grid(x1, y1, x2, y2, n):
        side_length = (x2 - x1) / (n + 1)
        grid = []
        for i in range(n + 1):
            for j in range(n + 1):
                x = x1 + i * side_length
                y = y1 + j * side_length * math.sqrt(3)
                hexagon = hexagon_coordinates(x, y, side_length)
                grid.append(hexagon)
        return grid

    return hexagon_grid(x1, y1, x2, y2, n)

