    else:
        return y

def candidate(num):
    even = 0
    odd = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even += 1
        else:
            odd += 1
    return even, odd

def count_common(words):
    counts = {}
    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    return sorted_counts[:4]

def find_first_duplicate(nums):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] == nums[j]:
                return nums[i]
    return -1

def freq_element(lst):
    from collections import Counter
    flat_list = [item for sublist in lst for item in sublist]
    return dict(Counter(flat_list))

def count_With_Odd_SetBits(n):
    count = 0
    for i in range(1, n+1):
        binary_rep = bin(i)[2:]
        set_bits = binary_rep.count('1')
        if set_bits % 2 == 1:
            count += 1
    return count

def freq_count(lst):
    freq = {}
    for item in lst:
        freq[item] = freq.get(item, 0) + 1
    return freq

def get_pell(n):
    pell_numbers = [0, 1]
    for i in range(2, n+1):
        pell_numbers.append(2 * pell_numbers[i-1] + pell_numbers[i-2])
    return pell_numbers[n]

def is_valid_parenthese(s):
    stack = []
    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top = stack.pop()
            if (char == ")" and top != "(") or (char == "]" and top != "[") or (char == "}" and top != "{"):
                return False
    return not stack

def check_String(string):
    has_letter = False
    has_number = False
    for char in string:
        if char.isalpha():
            has_letter = True
        elif char.isdigit():
            has_number = True
        if has_letter and has_number:
            return True
    return False

def octal_To_Decimal(octal_number):
    decimal_number = 0
    for i, digit in enumerate(reversed(str(octal_number))):
        decimal_number += int(digit) * (8 ** i)
    return decimal_number

def first_Repeated_Char(s):
    for i in range(len(s)):
        if s[i] in s[:i]:
            return s[i]
    return '\0'

def re_arrange_array(arr, n):
    for i in range(n):
        if arr[i] >= 0:
            for j in range(i+1, n):
                if arr[j] < 0:
                    arr[i], arr[j] = arr[j], arr[i]
                    break
    return arr

def babylonian_squareroot(num):
    guess = num / 2
    while True:
        new_guess = (guess + num / guess) / 2
        if abs(new_guess - guess) < 1e-10:
            return new_guess
        guess = new_guess

def sequential_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return True, i
    return False, -1

def set_Bit_Number(n):
    if n == 0:
        return 0
    msb = 0
    while n > 1:
        n = n >> 1
        msb += 1
    return 1 << msb

def char_frequency(string):
    frequency = {}
    for char in string:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

def max_occurrences(lst):
    counts = {}
    for item in lst:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
    max_item = max(counts, key=counts.get)
