def get_max_sum(n):
    if n <= 5:
        return n
    else:
        return max(get_max_sum(n//2) + get_max_sum(n//3) + get_max_sum(n//4) + get_max_sum(n//5), n)

def find_Parity(num):
    count = 0
    while num > 0:
        count += num & 1
        num >>= 1
    return "Even Parity" if count % 2 == 0 else "Odd Parity"

def count_Occurrence(tup, lst):
