def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def is_Sub_Array(arr1, arr2, n, m):
    for i in range(n):
        if arr1[i] == arr2[0]:
            j = 1
            while j < m and i+j < n and arr1[i+j] == arr2[j]:
                j += 1
            if j == m:
                return True
    return False

def prime_num(n):
    if n < 2:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def find_literals(string, pattern):
    import re
    matches = re.search(pattern, string)
    if matches:
        return matches.group(), matches.start(), matches.end()
    else:
        return None

def move_num(s):
    nums = [char for char in s if char.isdigit()]
    return ''.join([char for char in s if not char.isdigit()]) + ''.join(nums)

def max_occurrences(lst):
    counts = {}
    max_item = None
    max_count = 0
    for item in lst:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
        if counts[item] > max_count:
            max_item = item
            max_count = counts[item]
    return max_item

def average_Even(n):
    if n % 2 != 0:
        return None
    total = 0
    count = 0
    for i in range(2, n+1, 2):
        total += i
        count += 1
    return total // count

def smallest_Divisor(n):
