    return -1

def sum_Of_Subarray_Prod(arr, n):
    sum_prod = 0
    for i in range(n):
        prod = 1
        for j in range(i, n):
            prod *= arr[j]
            sum_prod += prod
    return sum_prod

def max_run_uppercase(s):
    max_run = 0
    current_run = 0
    for char in s:
        if char.isupper():
            current_run += 1
        else:
            max_run = max(max_run, current_run)
            current_run = 0
    max_run = max(max_run, current_run)
    return max_run

def count_alpha_dig_spl(input_str):
