def candidate(l):
    l.sort()
    n = len(l)
    if n % 2 == 0:
        return (l[n//2 - 1] + l[n//2]) / 2
    else:
        return l[n//2]

def candidate(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return candidate(n - 1) + candidate(n - 2)
